let page='overview',tool='select',catalogQuery='',catalogCategory='Все',toastTimer,dragState=null,providerStatus={},shoppingPanel='',drawStart=null; let undoStack=[],redoStack=[];try{undoStack=JSON.parse(localStorage.getItem('domproekt.history')||'[]')}catch{} let lastSnapshot=JSON.stringify(project);
