function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function save(){const snap=JSON.stringify(project);if(lastSnapshot&&snap!==lastSnapshot){undoStack.push(lastSnapshot);if(undoStack.length>100)undoStack.shift();redoStack=[];localStorage.setItem('domproekt.history',JSON.stringify(undoStack));}lastSnapshot=snap;localStorage.setItem(STORE,snap);document.querySelector('#save-status').textContent='Сохранено';clearTimeout(save.timer);save.timer=setTimeout(()=>{fetch('/api/project',{method:'PUT',headers:{'content-type':'application/json'},body:snap}).catch(()=>{});},350)} function restoreHistory(from,to){if(!from.length){toast('История изменений пуста');return}to.push(JSON.stringify(project));project=JSON.parse(from.pop());lastSnapshot=JSON.stringify(project);localStorage.setItem(STORE,lastSnapshot);localStorage.setItem('domproekt.history',JSON.stringify(undoStack));fetch('/api/project',{method:'PUT',headers:{'content-type':'application/json'},body:lastSnapshot}).catch(()=>{});render()} function roomMetrics(r){const w=Number(r.widthM)||1,d=Number(r.depthM)||1,h=Number(r.ceilingM)||2.7;return {area:w*d,perimeter:2*(w+d),volume:w*d*h}} function roomW(r){return Math.max(30,Number(r.widthM||1)*50)} function roomH(r){return Math.max(30,Number(r.depthM||1)*50)}
