function firstIncomplete(){return journeySteps.findIndex(x=>!project.journey.completed.includes(x.id))}
function go(p){if(p==='catalog'||p==='tile'){shoppingPanel=p; p='shopping'}if(p==='overview'){page='overview';render();return}const idx=journeySteps.findIndex(x=>x.id===p);if(idx<0)return;const pending=firstIncomplete(),next=pending<0?journeySteps.length:pending;if(idx>next){toast('Сначала завершите предыдущий шаг проекта');return}page=p;project.journey.currentStep=idx;save();render()}
function journeyHeader(){const idx=journeySteps.findIndex(x=>x.id===page),done=project.journey.completed.length,percent=Math.round(done/journeySteps.length*100);return `<div class="journey-header"><div class="journey-position"><b>Шаг ${idx+1} из ${journeySteps.length}</b> · ${journeySteps[idx]?.name||''}</div><div class="journey-track"><i style="width:${percent}%"></i></div><span class="journey-position">${percent}%</span></div>`}
function journeyFooter(){const idx=journeySteps.findIndex(x=>x.id===page),prev=idx===0?'overview':journeySteps[idx-1].id;const done=project.journey.completed.includes(page);const label=idx===journeySteps.length-1?(project.journey.finished?'Готово':'Завершить проект'):done?'Продолжить →':'Сохранить и продолжить →';return `<div class="journey-controls"><button class="button" data-action="previous-step">← Назад</button><p>${done?'Шаг сохранён. Вы можете вернуться сюда позже.':'Изменения сохраняются автоматически; продолжайте, когда будете готовы.'}</p><button class="button primary" data-action="complete-step">${label}</button></div>`}
function refreshJourneyNav(){const next=firstIncomplete()<0?journeySteps.length:firstIncomplete();document.querySelectorAll('.journey-item').forEach((el,i)=>{const id=el.dataset.page,completed=project.journey.completed.includes(id);el.classList.toggle('active',page===id);el.classList.toggle('current',page===id);el.classList.toggle('completed',completed);el.classList.toggle('locked',i>next&&!completed);el.setAttribute('aria-current',page===id?'step':'false');const num=el.querySelector('.journey-num');if(num)num.textContent=completed?'✓':String(i+1).padStart(2,'0')});const idx=journeySteps.findIndex(x=>x.id===page);document.querySelector('#top-step').textContent=idx<0?'Старт проекта':`Шаг ${idx+1} из 6`}
function resumeJourney(){const next=journeySteps[firstIncomplete()]||journeySteps.at(-1);go(next.id)}
function completeCurrentStep(){const idx=journeySteps.findIndex(x=>x.id===page);if(idx<0)return;if(page==='plan'&&!project.rooms.length){toast('Добавьте хотя бы одну комнату перед продолжением');return}if(page==='design'&&!project.selectedDesignId){toast('Выберите один из вариантов дизайна, чтобы продолжить');return}project.journey.completed=[...new Set([...project.journey.completed,page])];save();if(idx===journeySteps.length-1){project.journey.finished=true;save();render();toast('Проектный путь завершён');return}go(journeySteps[idx+1].id)}
function skipEngineering(){project.journey.completed=[...new Set([...project.journey.completed,'engineering'])];project.journey.skippedEngineering=true;save();go('style')}
function heading(k,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
