function overview(){const area=project.rooms.reduce((sum,r)=>sum+roomMetrics(r).area,0),done=project.journey.completed.length,total=journeySteps.length,progress=Math.round(done/total*100),next=journeySteps[firstIncomplete()]||journeySteps.at(-1);return `${heading('ВАШ ПРОЕКТ','От плана до готового списка покупок',`Проходите шаги по порядку. К предыдущим этапам можно вернуться в любой момент.`,`<button class="button" data-action="rename">✎ Параметры проекта</button><button class="button primary" data-action="resume">${done?'Продолжить':'Начать проект'} <span>→</span></button>`)}<div class="overview-grid"><section class="card hero-card"><div class="hero-copy"><span class="pill ok">${project.journey.finished?'● Проект завершён':'● Следующий шаг'}</span><h2>${safe(next.name)}<br>— продолжим здесь</h2><p>${project.journey.finished?'Ваш путь от планировки до сметы завершён. Вы можете вернуться к любому этапу.':`Шаг ${firstIncomplete()+1} из ${total}. ${next.id==='engineering'?'Инженерию можно пропустить.':'Следуйте по маршруту, чтобы связать план, дизайн, покупки и бюджет.'}`}</p><button class="button soft" data-action="resume">${project.journey.finished?'Открыть смету':'Перейти к шагу'} <span>→</span></button></div><div class="hero-illustration"><svg viewBox="0 0 290 180"><ellipse cx="155" cy="155" rx="116" ry="12" fill="#dfe5db"/><path d="M32 122 148 57l114 54-118 66z" fill="#d5d1c5"/><path d="M32 122v-65l113-47 3 47z" fill="#f4f1e8"/><path d="m148 57 114-51v105l-118 66z" fill="#e5e6dc"/><path d="m48 91 65-28v38l-65 30z" fill="#c4c9ba"/><path d="m165 64 78-34v41l-78 35z" fill="#b8c8b3"/><path d="m84 138 42-24 39 20-43 26z" fill="#b4a994"/><path d="m102 134 24-13 22 12-23 14z" fill="#8b9b84"/></svg></div></section><section class="card stat-card"><div class="stat-head"><span>ПРОХОД ПО МАРШРУТУ</span><span class="stat-icon">◒</span></div><div><div class="big-stat">${done} <small style="font-size:13px;font-weight:500">из ${total} шагов</small></div><div class="stat-sub">${project.journey.finished?'Маршрут завершён':`${next.name} — следующий этап`}</div><div class="progress-track"><i style="width:${progress}%"></i></div><div class="progress-copy"><span>Планировка</span><span>${progress}%</span></div></div></section></div><div class="section-row"><h2>Сводка проекта</h2><span class="pill">${safe(project.city)}</span></div><div class="metric-row"><div class="card metric"><label>ОБЩАЯ ПЛОЩАДЬ</label><strong>${area.toFixed(1)} м²</strong><small>${project.rooms.length} помещений</small></div><div class="card metric"><label>КОМНАТЫ</label><strong>${project.rooms.length}</strong><small>на ${project.floor}-м этаже</small></div><div class="card metric"><label>ИНЖЕНЕРНЫЕ ТОЧКИ</label><strong>${project.points.length}</strong><small>электрика и коммуникации</small></div><div class="card metric"><label>ТЕКУЩАЯ ОЦЕНКА</label><strong>${money(estimateTotal())}</strong><small>черновая смета</small></div></div><div class="section-row"><h2>Ваш маршрут</h2><span style="font-size:9px;color:#969d93">Шаги открываются по мере прохождения</span></div><section class="card steps-card">${journeySteps.map((s,i)=>{const complete=project.journey.completed.includes(s.id),active=s.id===next.id;return `<div class="step-line"><div class="step-num">${complete?'✓':String(i+1).padStart(2,'0')}</div><div><b>${s.name}</b><small>${complete?'Готово':active?'Текущий шаг':'Откроется после предыдущего шага'}</small></div>${complete||active?`<button data-page="${s.id}">${complete?'Вернуться':'Открыть'} →</button>`:'<span class="pill">далее</span>'}</div>`}).join('')}</section>`}
function layerVisible(kind){return ({socket:project.layers.electricity,light:project.layers.electricity,switch:project.layers.electricity,panel:project.layers.electricity,water:project.layers.water,drain:project.layers.water,radiator:project.layers.heating,heating:project.layers.heating,vent:project.layers.ventilation})[kind]??true} function floorSvg(engine=false){const rooms=project.rooms.filter(r=>(r.floor||1)===project.floor);const wallMarkup=(project.walls||[]).filter(w=>(w.floor||1)===project.floor).map(w=>`<g class="plan-wall" data-wall="${w.id}"><line x1="${w.x1}" y1="${w.y1}" x2="${w.x2}" y2="${w.y2}" stroke="${w.type==="bearing"?'#39453b':w.type==="wet"?'#5e9aa4':'#7d877b'}" stroke-width="${Math.max(4,(Number(w.thickness)||100)/25)}" stroke-linecap="square"/><title>${safe(w.name||"Стена")} · ${safe(w.type)} · ${(Math.hypot(w.x2-w.x1,w.y2-w.y1)/50).toFixed(2)} м</title></g>`).join("");const openingMarkup=(project.openings||[]).filter(o=>(o.floor||1)===project.floor).map(o=>`<g class="plan-opening" transform="translate(${o.x} ${o.y})"><circle r="9" fill="#fff" stroke="#788375"/><text y="3" text-anchor="middle" font-size="8" fill="#485447">${o.kind==="window"?'О':'Д'}</text></g>`).join("");const routeMarkup=(project.routes||[]).filter(x=>(x.floor||1)===project.floor&&layerVisible(x.kind)).map(x=>`<g><polyline points="${x.x1},${x.y1} ${x.x2},${x.y1} ${x.x2},${x.y2}" fill="none" stroke="${x.kind==="electric"?"#7191bd":x.kind==="water"?"#5e9aa4":x.kind==="heating"?"#bd795d":"#75a79a"}" stroke-width="3" stroke-dasharray="6 3"/><title>${safe(x.name)} · ${x.length.toFixed(2)} м</title></g>`).join("");const itemMarkup=project.layers.furniture?project.items.filter(i=>(i.floor||1)===project.floor).map(i=>{let glyph={sofa:'🛋',table:'▱',bed:'▰',plant:'♣',chair:'◒',cabinet:'▤',desk:'▱'}[i.kind]||'◉';return `<g class="drag-item" data-id="${i.id}" data-type="furniture" transform="translate(${i.x} ${i.y})"><rect x="-22" y="-14" width="44" height="28" rx="4" fill="#c8d4c0" stroke="#91a287"/><text text-anchor="middle" y="5" font-size="16">${glyph}</text></g>`}).join(''):'';const pointMarkup=project.points.filter(p=>(p.floor||1)===project.floor).map(p=>{let cfg={socket:['#7191bd','⌑'],light:['#d4a44e','✳'],water:['#5e9aa4','●'],switch:['#9d83b0','◉'],radiator:['#bd795d','▥'],vent:['#75a79a','⊙']}[p.kind]||['#709a76','●'];let visible=layerVisible(p.kind);return visible?`<g class="drag-item" data-id="${p.id}" data-type="point" transform="translate(${p.x} ${p.y})"><circle r="10" fill="${cfg[0]}"/><text text-anchor="middle" y="4" font-size="10" fill="white">${cfg[1]}</text></g>`:''}).join('');return `<svg id="floor-svg" viewBox="0 0 740 500" aria-label="План помещений" ${engine?'class="engine-plan"':''}><defs><pattern id="smallGrid" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M18 0H0V18" fill="none" stroke="#e8ebe5" stroke-width=".6"/></pattern><pattern id="bigGrid" width="90" height="90" patternUnits="userSpaceOnUse"><rect width="90" height="90" fill="url(#smallGrid)"/><path d="M90 0H0V90" fill="none" stroke="#dce1d9" stroke-width=".9"/></pattern></defs><rect width="740" height="500" fill="url(#bigGrid)"/>${rooms.map(r=>`<g class="room-shape" data-room="${r.id}"><rect x="${r.x}" y="${r.y}" width="${roomW(r)}" height="${roomH(r)}" fill="${r.color}" stroke="#5a6858" stroke-width="5"/><path d="M${r.x+roomW(r)/2-30} ${r.y+roomH(r)}h60" stroke="#f8f8f5" stroke-width="6"/><text x="${r.x+roomW(r)/2}" y="${r.y+roomH(r)/2-3}" text-anchor="middle" font-size="12" fill="#555f53" font-weight="600">${safe(r.name)}</text><text x="${r.x+roomW(r)/2}" y="${r.y+roomH(r)/2+14}" text-anchor="middle" font-size="9" fill="#879082">${roomMetrics(r).area.toFixed(1)} м²</text></g>`).join('')}${wallMarkup}${openingMarkup}${routeMarkup}${itemMarkup}${pointMarkup}<text x="23" y="25" font-size="9" fill="#9ba295">СЕТКА 100 мм</text></svg>`}
function plan(){return `${heading('ШАГ 01 · МОДЕЛЬ ПОМЕЩЕНИЙ','Планировка',`Создайте точную основу проекта. Перетаскивайте предметы и отмечайте размеры комнат.`,`<button class="button" data-action="undo">↶</button><button class="button" data-action="redo">↷</button><button class="button" data-action="export-plan-png">PNG ↓</button><button class="button" data-action="export-plan-svg">SVG ↓</button><button class="button" data-action="export-plan-dxf">DXF ↓</button><button class="button" data-action="import-plan-dxf">DXF ↑</button><button class="button primary" data-action="add-room">＋ Добавить комнату</button>`)}<div class="editor-layout"><section class="card editor-card"><div class="editor-toolbar"><button class="tool-btn ${tool==='select'?'active':''}" data-tool="select">↖ Выбор</button><button class="tool-btn ${tool==='room'?'active':''}" data-tool="room">＋ Комната</button><button class="tool-btn ${tool==='furniture'?'active':''}" data-tool="furniture">▱ Мебель</button><button class="tool-btn ${tool==='socket'?'active':''}" data-tool="socket">⌑ Розетка</button><button class="tool-btn ${tool==="wall"?'active':''}" data-tool="wall">╱ Стена</button><button class="tool-btn" data-action="add-opening">▯ Проём</button><span class="toolbar-spacer"></span><select class="floor-select" id="floor-select">${[...new Set([...(project.floors||[1]),project.floor])].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${project.floor===n?"selected":""}>${n} этаж</option>`).join("")}<option value="add">＋ Добавить этаж</option></select><button class="tool-btn" data-action="toggle-furniture">▣ Слои</button></div><div class="canvas-wrap"><input id="plan-file" type="file" accept=".dxf" hidden>${floorSvg()}<div class="canvas-note">Перетаскивайте мебель и точки · масштаб схематичный</div><div class="canvas-zoom"><button data-action="zoom-out">−</button><button>100%</button><button data-action="zoom-in">＋</button></div></div><div class="summary-strip"><strong>${project.rooms.length} помещения</strong><span>·</span><span>${project.rooms.reduce((a,r)=>a+roomMetrics(r).area,0).toFixed(1)} м² общая площадь</span><span style="margin-left:auto">Автосохранение включено</span></div></section><aside class="editor-side"><section class="card side-panel"><h3>Добавить на план</h3><div class="tool-palette"><button class="palette-item" data-add="room"><b>＋</b>Комната</button><button class="palette-item" data-add="sofa"><b>▰</b>Диван</button><button class="palette-item" data-add="table"><b>▱</b>Стол</button><button class="palette-item" data-add="bed"><b>▰</b>Кровать</button><button class="palette-item" data-add="plant"><b>♣</b>Растение</button><button class="palette-item" data-add="socket"><b>⌑</b>Розетка</button></div></section><section class="card side-panel"><h3>Помещения <button class="text-button" data-action="add-room" style="float:right">＋ Добавить</button></h3><table class="room-table"><thead><tr><th>НАЗВАНИЕ</th><th>ПЛОЩАДЬ</th><th></th></tr></thead><tbody>${project.rooms.map(r=>`<tr><td><span class="room-dot" style="background:${r.color}"></span>${safe(r.name)}</td><td>${roomMetrics(r).area.toFixed(1)} м²</td><td><button class="text-button" data-edit-room="${r.id}">✎</button> <button class="text-button" data-remove-room="${r.id}">×</button></td></tr>`).join('')}</tbody></table></section><section class="card side-panel"><h3>Параметры проекта</h3><div class="property-row"><span>Город</span><strong>${safe(project.city)}</strong></div><div class="property-row"><span>Потолки</span><strong>2,70 м</strong></div><div class="property-row"><span>Масштаб</span><strong>1 : 50</strong></div><button class="text-button" data-action="rename" style="margin-top:10px">Изменить параметры →</button></section></aside></div>`}
function engineering(){const icon={socket:'⌑',light:'✳',water:'●',switch:'◉',radiator:'▥',vent:'⊙'};return `${heading('ШАГ 02 · ИНЖЕНЕРНЫЕ СИСТЕМЫ','Инженерия',`Разместите точки электрики и коммуникаций. Здесь они отображаются отдельным слоем плана.`,`<button class="button" data-action="toggle-engine-layer">${project.layers.electricity?'◉':'◎'} Электрика</button><button class="button" data-action="toggle-water">Вода</button><button class="button" data-action="toggle-heating">Отопление</button><button class="button" data-action="toggle-vent">Вентиляция</button><button class="button" data-action="skip-engineering">Пропустить шаг</button><button class="button" data-action="add-route">＋ Трасса</button><button class="button primary" data-action="add-point">＋ Добавить точку</button>`)}<div class="engine-grid"><section class="card" style="padding:15px"><div class="section-row" style="margin:0 0 10px"><h2>Схема инженерных точек</h2><span class="pill">План · ${project.floor} этаж</span></div><div class="engine-canvas">${floorSvg(true)}</div><div class="engine-legend"><span class="legend-item"><i class="legend-dot" style="background:#7191bd"></i>Электрика</span><span class="legend-item"><i class="legend-dot" style="background:#5e9aa4"></i>Вода</span><span class="legend-item"><i class="legend-dot" style="background:#bd795d"></i>Отопление</span><span class="legend-item">Перетаскивайте точки по плану</span></div></section><section class="card side-panel"><h3>Точки проекта <span class="pill" style="float:right">${project.points.length}</span></h3><div class="engine-list">${project.points.map(p=>`<div class="engine-row"><span style="color:${({socket:'#7191bd',light:'#d4a44e',water:'#5e9aa4',switch:'#9d83b0',radiator:'#bd795d',vent:'#75a79a'})[p.kind]}">${icon[p.kind]||'●'}</span><div><b>${safe(p.name)}</b><small>${safe(project.rooms.find(r=>r.id===p.room)?.name||'Помещение')} · высота ${p.kind==='socket'?'300':p.kind==='switch'?'900':'2400'} мм</small></div><button data-remove-point="${p.id}">×</button></div>`).join('')||'<div class="empty-state">Добавьте первую точку на схему</div>'}</div><button class="button primary" data-action="add-point" style="width:100%;justify-content:center;margin-top:12px">＋ Новая точка</button><div class="warning-box">Проверки расстояний и нормативов в этой версии носят справочный характер. Схему следует проверить с профильным специалистом.</div></section></div>`}
function stylePage(){return `${heading('ШАГ 03 · ВАШИ ПОЖЕЛАНИЯ','Выберите направление дизайна','Опишите настроение, материалы и приоритеты. На следующем шаге ИИ предложит несколько вариантов.') }<div class="design-layout"><section class="card design-settings"><div class="eyebrow">СТИЛЬ И НАСТРОЕНИЕ</div><div class="style-grid">${styles.map(s=>`<button class="style-chip ${project.style===s[0]?'active':''}" data-style="${s[0]}"><i style="background:${s[1]}"></i>${s[0]}</button>`).join('')}</div><label for="prompt">Расскажите о своём интерьере</label><textarea id="prompt" class="textarea" placeholder="Например: светлая кухня-гостиная, дерево и чёрный металл, без глянца…">${safe(project.prompt)}</textarea><div class="reference-upload"><div class="section-row" style="margin:10px 0"><b>Референсы · до 20 изображений</b><button type="button" class="button small" data-action="add-references">＋ Загрузить</button></div><input id="reference-files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><div class="reference-grid">${(project.referenceImages||[]).map((r,i)=>`<figure><img src="${safe(r.url)}" alt="Референс ${i+1}"><button type="button" data-remove-reference="${safe(r.id)}" aria-label="Удалить референс">×</button></figure>`).join('')}</div><div class="step-helper">JPG, PNG, WebP до 10 МБ каждый. При генерации выбранный провайдер ИИ получит эти изображения.</div></div><label for="budget">Бюджет на мебель и отделку, ₽</label><input id="budget" class="input" type="number" min="0" value="${project.budget||500000}"><div class="preferences-grid"><div class="design-rooms"><label class="field-label">Комнаты для дизайна</label>${project.rooms.map(r=>`<label class="check-row"><input type="checkbox" data-design-room="${safe(r.id)}" ${(project.preferences.designRooms||[]).length===0||(project.preferences.designRooms||[]).includes(r.id)?'checked':''}>${safe(r.name)}</label>`).join('')}</div><label class="field-label">Жильцов <input class="input" type="number" min="1" max="20" data-pref="occupants" value="${project.preferences.occupants||1}"></label><label class="check-row"><input type="checkbox" data-pref="children" ${project.preferences.children?'checked':''}> Есть дети</label><label class="check-row"><input type="checkbox" data-pref="pets" ${project.preferences.pets?'checked':''}> Есть животные</label></div><label class="field-label">Обязательные предметы</label><input class="input" data-pref="mustHave" value="${safe(project.preferences.mustHave||'')}" placeholder="Рабочий стол, шкаф для хранения…"><label class="field-label">Исключить цвета или материалы</label><input class="input" data-pref="avoid" value="${safe(project.preferences.avoid||'')}" placeholder="Глянец, ярко-красный цвет…"><label class="check-row"><input id="reference-consent" type="checkbox" ${project.referenceConsent?'checked':''}> Передать загруженные референсы выбранному ИИ при генерации</label><div class="step-helper">Можно написать свободным текстом, выбрать готовый стиль или сочетать оба способа.</div></section><section class="card" style="padding:20px"><div class="eyebrow">ВАШ ПРОЕКТ</div><h3 style="font:700 15px Manrope;margin:8px 0">${safe(project.style)}</h3><p style="font-size:10px;line-height:1.6;color:#838b80">${safe(project.prompt||'Добавьте пожелания — стиль станет основой для подбора мебели и отделки.')}</p><div class="property-row"><span>Бюджет</span><strong>${money(project.budget||0)}</strong></div><div class="property-row"><span>Комнаты</span><strong>${project.rooms.length}</strong></div><div class="property-row"><span>Город</span><strong>${safe(project.city)}</strong></div><div class="warning-box">Каталог товаров доступен на шаге «Покупки и плитка». Варианты дизайна будут использовать только импортированные товары с размерами.</div></section></div>`}
function design(){const selected=project.designs.find(d=>d.id===project.selectedDesignId);const cards=project.designs.map((d,i)=>{const products=d.productIds.map(id=>project.products.find(p=>p.id===id)).filter(Boolean);return `<article class="card variant-card ${project.selectedDesignId===d.id?'variant-selected':''}"><div class="variant-thumb"><span>${['✳','◉','✦'][i%3]}</span></div><div class="variant-content"><div class="eyebrow">ВАРИАНТ ${i+1} · ${safe(d.provider||'демо')}</div><h3>${safe(d.name)}</h3><p>${safe(d.description)}</p><div class="tag-list">${products.map(p=>`<span class="tag">${safe(p.name)}</span>`).join('')||'<span class="tag">В каталоге нет подходящих позиций</span>'}</div><button class="button ${project.selectedDesignId===d.id?'soft':'primary'} small" data-select-design="${safe(d.id)}" style="margin-top:11px">${project.selectedDesignId===d.id?'✓ Выбрано':'Выбрать вариант'}</button></div></article>`}).join('');return `${heading('ШАГ 04 · СОЗДАНИЕ ПРОЕКТА','Сравните варианты дизайна','Сгенерируйте 2–3 концепции и выберите одну для списка покупок.',`<select id="provider" class="select" style="width:auto"><option value="local">Демо-режим</option><option value="openai">ChatGPT / OpenAI ${providerStatus.openai?'· подключён':'· нужен ключ'}</option><option value="gemini">Gemini ${providerStatus.gemini?'· подключён':'· нужен ключ'}</option></select><button class="button primary" data-action="generate">✳ Создать варианты</button>`)}${project.designs.length?`<div class="variant-compare">${cards}</div><div class="card" style="padding:12px 14px;margin-top:12px;font-size:10px;color:#798275">${selected?`Выбран вариант: <b>${safe(selected.name)}</b>. Состав покупок можно изменить на следующем шаге.`:'Выберите вариант, чтобы продолжить к списку покупок.'}</div>`:`<div class="card design-empty"><div><div class="empty-symbol">✳</div><h3>Сначала создадим варианты</h3><p>ИИ использует стиль и пожелания с предыдущего шага, а товары берёт только из каталога проекта.</p><button class="button primary" data-action="generate" style="margin-top:13px">Создать 2–3 варианта</button></div></div>`}`}
function retailerPanel(){const locals=retailSources.cities?.[project.city]||retailSources.fallback||[];const globals=(retailSources.global||[]).filter(s=>s.id!=='lemana'||!locals.some(x=>x.id.includes('lemana')));const entries=[...globals,...locals,{id:"local-map",name:`Местные магазины · ${project.city}`,kind:"Поиск по городу",catalogUrl:`https://yandex.ru/maps/?text=${encodeURIComponent(`строительные магазины ${project.city}`)}`,integration:"Найти строительные магазины поблизости. Чтобы добавить их товары в проект, запросите фид или импортируйте каталог продавца.",status:"search_link"}];const avCity=({Самара:'samara',Казань:'kazan',Москва:'moskva',Екатеринбург:'ekaterinburg',Новосибирск:'novosibirsk','Санкт-Петербург':'sankt-peterburg',Краснодар:'krasnodar',Уфа:'ufa',Пермь:'perm',Воронеж:'voronezh'})[project.city]||'rossiya';return `<section class="card source-panel"><div class="section-row" style="margin:0 0 11px"><div><h2>Магазины и источники · ${safe(project.city)}</h2><div style="font-size:9px;color:#969d93;margin-top:4px">Розничные витрины и локальные каталоги для этого города</div></div><button class="text-button" data-action="import-feed">Импортировать фид ↥</button></div><div class="source-grid">${entries.map(s=>{const url=s.id==='avito'?`https://www.avito.ru/${avCity}?q=${encodeURIComponent('стройматериалы мебель ремонт')}`:s.catalogUrl;const label=({api_application:'ДОСТУП К API',feed_request:'ЗАПРОСИТЬ ФИД',search_link:'ПОИСК ПО ГОРОДУ',manual_feed:'ИМПОРТ КАТАЛОГА'})[s.status]||'ПОДКЛЮЧИТЬ';return `<article class="source-card"><div class="source-top"><span class="source-icon">${s.id==='avito'?'а':s.name.slice(0,1)}</span><span class="source-kind">${safe(s.kind)}</span></div><h3>${safe(s.name)}</h3><p>${safe(s.integration)}</p><div class="source-actions"><a href="${safe(url)}" target="_blank" rel="noopener">Каталог ↗</a>${s.docsUrl?`<a href="${safe(s.docsUrl)}" target="_blank" rel="noopener">Интеграция ↗</a>`:''}</div><div class="source-status">${label}</div></article>`}).join('')}</div>${project.catalogImports?.length?`<div class="source-import-note">Импортировано файлов: ${project.catalogImports.length} · последняя синхронизация: ${safe(project.catalogImports.at(-1).date)}</div>`:''}</section>`}
function catalog(){let items=project.products.filter(p=>(catalogCategory==='Все'||p.category===catalogCategory)&&(`${p.name} ${p.category} ${p.brand} ${p.tags.join(' ')}`.toLowerCase().includes(catalogQuery.toLowerCase())));return `${heading('КАТАЛОГ · МАТЕРИАЛЫ И МЕБЕЛЬ','Каталог товаров',`Дизайн использует только позиции, сохранённые в каталоге проекта.`,`<button class="button" data-action="import-feed">↥ Импорт фида</button><button class="button primary" data-action="add-product">＋ Добавить товар</button>`)}<div class="demo-banner"><span>ⓘ</span><span>В стартовом каталоге есть демонстрационные цены и ссылки на поиск по магазину. Для коммерческой сметы подключите официальные фиды и региональные остатки; все демо-позиции отмечены в карточках.</span></div>${retailerPanel()}<input id="feed-file" type="file" accept=".yml,.yaml,.xml,.csv,.json" hidden><div class="catalog-toolbar"><input id="catalog-search" class="input" placeholder="⌕  Поиск по названию и материалу" value="${safe(catalogQuery)}"><select id="catalog-category" class="select" style="max-width:170px"><option>Все</option>${[...new Set(project.products.map(p=>p.category))].map(c=>`<option ${catalogCategory===c?'selected':''}>${safe(c)}</option>`).join('')}</select><span style="align-self:center;font-size:10px;color:#969c93;margin-left:auto">${items.length} позиций</span></div><div class="product-grid">${items.map(p=>`<article class="card product-card"><div class="product-art"><span class="product-label">${p.updated==='Демо'?'ДЕМО · '+safe(p.category):safe(p.category)}</span><span class="emoji">${p.emoji||'▦'}</span></div><div class="product-info"><h3>${safe(p.name)}</h3><p>${safe(p.brand)} · ${safe(p.dimensions)}</p><div class="product-price"><strong>${money(p.price)}</strong><a href="${safe(p.url)}" target="_blank" rel="noopener">${safe(p.store)} ↗</a></div><button class="button small" data-add-shopping="${safe(p.id)}" style="width:100%;justify-content:center;margin-top:8px">＋ Добавить в список покупок</button></div></article>`).join('')||'<div class="card empty-state">По вашему запросу ничего не найдено</div>'}</div>`}
function shopping(){const chosen=project.designs.find(d=>d.id===project.selectedDesignId),ids=[...new Set([...(chosen?.productIds||[]),...(project.manualShopping||[])])].filter(id=>!(project.shoppingExclusions||[]).includes(id)),items=ids.map(id=>project.products.find(p=>p.id===id)).filter(Boolean),qty=p=>Math.max(1,Number(project.shoppingQuantities?.[p.id])||1),productsTotal=items.reduce((sum,p)=>sum+(Number(p.price)||0)*qty(p),0),groups=[...new Set(items.map(p=>p.store||'Магазин'))].map(store=>({store,rows:items.filter(p=>(p.store||'Магазин')===store)}));return `${heading('ШАГ 05 · ПОКУПКИ И ОТДЕЛКА','Список покупок','Соберите товары для выбранного дизайна, сравните суммы по магазинам и рассчитайте плитку.',`<button class="button" data-action="export-shopping">⇩ Excel / CSV</button><button class="button" data-action="print">PDF / Печать</button>`)}<section class="card shopping-section"><div class="section-row" style="margin:0 0 8px"><div><h2>${chosen?safe(chosen.name):'Вариант дизайна не выбран'}</h2><div style="font-size:9px;color:#929a8f;margin-top:4px">${items.length} товарных позиций · ${money(productsTotal)}</div></div><button class="button small" data-go="design">Изменить дизайн</button></div>${groups.map(g=>`<section class="store-group"><div class="property-row"><b>${safe(g.store)}</b><strong>${money(g.rows.reduce((sum,p)=>sum+(Number(p.price)||0)*qty(p),0))}</strong></div>${g.rows.map(p=>`<div class="purchase-row"><span class="purchase-art">${p.image?`<img src="${safe(p.image)}" alt="">`:p.emoji||'▦'}</span><span><b>${safe(p.name)}</b><small>${safe(p.store)} · ${safe(p.dimensions)} · ${p.updated==='Демо'?'демо-цена':`обновлено ${safe(p.updated)}`}</small><a href="${safe(p.url)}" target="_blank" rel="noopener">Карточка магазина ↗</a></span><span class="purchase-price">${money(p.price)}<small> за шт.</small></span><label class="quantity-field">Кол-во<input type="number" min="1" step="1" value="${qty(p)}" data-shopping-qty="${safe(p.id)}"></label><button class="text-button" data-remove-purchase="${safe(p.id)}" aria-label="Удалить товар">×</button></div>`).join('')}</section>`).join('')||`<div class="empty-state">${chosen?'Вариант не содержит товаров из каталога. Добавьте позиции ниже.':'Сначала выберите вариант дизайна на шаге 4.'}</div>`}<div class="step-helper">Цены и наличие из демонстрационных позиций нужно проверить у продавца. Итого выбранных товаров: ${money(productsTotal)}.</div></section><details class="shopping-details" data-panel="catalog" ${shoppingPanel==='catalog'?'open':''}><summary>Магазины и каталог товаров</summary><div class="details-content">${catalog()}</div></details><details class="shopping-details" data-panel="tile" ${shoppingPanel==='tile'?'open':''}><summary>Рассчитать раскладку плитки</summary><div class="details-content">${tile()}</div></details>`}
function tileCalc(){const t=project.tile,area=Math.max(0,(Number(t.width)||0)*(Number(t.height)||0)),tileArea=(Number(t.tileWidth)||.6)*(Number(t.tileHeight)||.6),stepW=(Number(t.tileWidth)||.6)+(Number(t.joint)||2)/1000,stepH=(Number(t.tileHeight)||.6)+(Number(t.joint)||2)/1000,cols=Math.ceil((Number(t.width)||0)/stepW),rows=Math.ceil((Number(t.height)||0)/stepH),base=cols*rows,rate=['Диагональ','Ёлочка'].includes(t.pattern)?Math.max(15,Number(t.waste)||10):Number(t.waste)||10,pieces=Math.ceil(base*(1+rate/100)),pack=8,packs=Math.ceil(pieces/pack),jointKg=area*.35,glueKg=area*4,cutW=(Number(t.width)||0)-(cols-1)*stepW,cutH=(Number(t.height)||0)-(rows-1)*stepH,minCut=Math.min(cutW,cutH);return {area,tileArea,cols,rows,base,pieces,packs,jointKg,glueKg,pack,rate,cutW,cutH,minCut,cutWarning:minCut<Math.min(Number(t.tileWidth)||.6,Number(t.tileHeight)||.6)/3}}
function tileGridSvg(t,c){const cols=Math.max(1,Math.min(c.cols,24)),rows=Math.max(1,Math.min(c.rows,16)),w=480/cols,h=250/rows;return `<svg class="tile-grid-view" viewBox="0 0 480 250" role="img" aria-label="Схема раскладки плитки: ${c.cols} столбцов, ${c.rows} рядов"><rect width="480" height="250" rx="8" fill="#eee8dc"/>${Array.from({length:rows},(_,y)=>Array.from({length:cols},(_,x)=>{const shift=t.pattern==='Диагональ'?((x+y)%2)*1.5:t.pattern==='Ёлочка'?(x+y)%2*2:0;return `<rect x="${x*w+1+shift}" y="${y*h+1}" width="${Math.max(1,w-2)}" height="${Math.max(1,h-2)}" rx="1" fill="${(x+y)%2?'#d6dfd2':'#e1e6dc'}" stroke="#aab5a6" stroke-width="1"/>`}).join('')).join('')}<text x="8" y="242" font-size="8" fill="#687265">${c.cols} × ${c.rows} · шов ${t.joint} мм</text></svg>`}
function tile(){const t=project.tile,c=tileCalc();return `${heading('РАСКЛАДКА ПЛИТКИ','Расчёт плитки',`Предварительный подсчёт по площади поверхности, размеру плитки и запасу.`,`<button class="button" data-go="catalog">Выбрать из каталога</button>`)}<div class="tile-layout"><section class="card tile-preview"><div class="section-row" style="margin:0"><h2>Схема поверхности</h2><span class="pill">Ванная · пол</span></div>${tileGridSvg(t,c)}<div style="height:24px"></div><div class="calc-list"><div class="calc-row"><span>Площадь поверхности</span><strong>${c.area.toFixed(2)} м²</strong></div><div class="calc-row"><span>Плитка без запаса</span><strong>${c.base} шт. · сетка ${c.cols} × ${c.rows}</strong></div><div class="calc-row"><span>С запасом ${c.rate}%</span><strong>${c.pieces} шт. · ${c.packs} упаковок</strong></div><div class="calc-row"><span>Клей (ориентир 4 кг/м²)</span><strong>${c.glueKg.toFixed(1)} кг</strong></div><div class="calc-row"><span>Затирка (ориентир 0,35 кг/м²)</span><strong>${c.jointKg.toFixed(1)} кг</strong></div></div></section><section class="card side-panel"><h3>Параметры расчёта</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><div><label class="field-label">Длина, м</label><input class="input tile-input" data-key="width" type="number" min=".1" step=".1" value="${t.width}"></div><div><label class="field-label">Ширина, м</label><input class="input tile-input" data-key="height" type="number" min=".1" step=".1" value="${t.height}"></div><div><label class="field-label">Плитка, ширина м</label><input class="input tile-input" data-key="tileWidth" type="number" min=".05" step=".05" value="${t.tileWidth}"></div><div><label class="field-label">Плитка, высота м</label><input class="input tile-input" data-key="tileHeight" type="number" min=".05" step=".05" value="${t.tileHeight}"></div></div><label class="field-label">Способ укладки</label><select id="tile-pattern" class="select">${['Прямая','Диагональ','Ёлочка'].map(x=>`<option ${t.pattern===x?'selected':''}>${x}</option>`).join('')}</select><label class="field-label">Ширина шва</label><select id="tile-joint" class="select">${[1,2,3,4,5].map(n=>`<option value="${n}" ${t.joint==n?'selected':''}>${n} мм</option>`).join('')}</select><label class="field-label">Запас на подрезку и бой</label><select id="tile-waste" class="select"><option value="10" ${t.waste==10?'selected':''}>10% · прямая укладка</option><option value="15" ${t.waste==15?'selected':''}>15% · сложная укладка</option><option value="20" ${t.waste==20?'selected':''}>20% · ручное значение</option></select><div class="warning-box">Расчёт не учитывает проёмы, ниши, направление рисунка, подрезку по контуру, геометрию швов и нормы производителя клея/затирки. Добавьте эти поправки до закупки.</div><div class="summary-strip">${c.cutWarning?`Проверьте узкую подрезку у края: минимальный остаток ${Math.round(c.minCut*1000)} мм.`:"Узких крайних подрезок по упрощённой сетке не выявлено."} · Для сложной укладки учтён запас ${c.rate}%.</div><div class="summary-strip">Расчёт плитки будет учтён в смете после продолжения маршрута.</div></section></div>`}
function estimateRows(){const cityFactor=cities[project.city]||1,level={Эконом:.82,Стандарт:1,Премиум:1.38}[project.workLevel]||1,rooms=project.rooms,area=rooms.reduce((a,r)=>a+roomMetrics(r).area,0),wallArea=rooms.reduce((a,r)=>a+roomMetrics(r).perimeter*(Number(r.ceilingM)||2.7),0),tc=tileCalc(),selected=project.designs.find(d=>d.id===project.selectedDesignId)||project.designs[0],ids=[...new Set([...(selected?.productIds||[]),...(project.manualShopping||[])])].filter(id=>!(project.shoppingExclusions||[]).includes(id)),items=ids.map(id=>project.products.find(p=>p.id===id)).filter(Boolean),qty=p=>Math.max(1,Number(project.shoppingQuantities?.[p.id])||1),furniture=items.filter(p=>!['Освещение','Декор'].includes(p.category)),decor=items.filter(p=>['Освещение','Декор'].includes(p.category)),electricLength=project.routes.filter(r=>r.kind==='electric').reduce((a,r)=>a+r.length,0),waterLength=project.routes.filter(r=>['water','drain'].includes(r.kind)).reduce((a,r)=>a+r.length,0),heatLength=project.routes.filter(r=>r.kind==='heating').reduce((a,r)=>a+r.length,0);let rows=[['Подготовка','Демонтаж и вывоз',area,450,'Оценочный справочник работ'],['Черновые работы','Стяжка пола',area,1450,'Оценочный справочник работ'],['Черновые работы','Штукатурка стен (оценка)',wallArea,680,'Оценочный справочник работ'],['Электрика','Установка точек',project.points.filter(p=>['socket','switch','light','panel'].includes(p.kind)).length,920,'Оценочный справочник работ'],['Электрика','Прокладка кабельных трасс',electricLength,120,'Оценочный справочник работ'],['Сантехника','Монтаж точек водоснабжения',project.points.filter(p=>p.kind==='water').length,2400,'Оценочный справочник работ'],['Сантехника','Прокладка водопровода и канализации',waterLength,950,'Оценочный справочник работ'],['Отопление','Монтаж отопительных трасс',heatLength,1200,'Оценочный справочник работ'],['Отделка','Напольное покрытие',area,1450,'Оценочный справочник работ'],['Плитка',`Плитка · ${tc.pieces} шт. с запасом`,tc.area,Number(project.products.find(p=>p.category==='Плитка')?.price)||1890,'Каталог проекта · демо'],['Материалы','Клей для плитки · ориентир',tc.glueKg,90,'Ориентир расхода'],['Материалы','Затирка · ориентир',tc.jointKg,250,'Ориентир расхода'],['Мебель и техника','Товары выбранного дизайна',furniture.reduce((a,p)=>a+qty(p),0),furniture.reduce((a,p)=>a+p.price*qty(p),0)/Math.max(1,furniture.reduce((a,p)=>a+qty(p),0)),'Каталог проекта'],['Освещение и декор','Свет и декор из каталога',decor.reduce((a,p)=>a+qty(p),0),decor.reduce((a,p)=>a+p.price*qty(p),0)/Math.max(1,decor.reduce((a,p)=>a+qty(p),0)),'Каталог проекта'],...project.addedLines.map(l=>[l.section,l.name,l.qty,l.price,'Добавлено пользователем'])];return rows.map(([section,name,qtyValue,unit,source],i)=>{const material=['Мебель и техника','Освещение и декор','Плитка','Материалы','Отделка'].includes(section),edit=project.estimateEdits?.['e'+i]||{},q=edit.qty??(Number(qtyValue)||0),u=edit.price??(Number(unit)||0),factor=material?1:cityFactor*level;return {id:'e'+i,section,name,qty:q,unit:u,amount:q*u*factor,source,factor}})}
function estimateTotal(){const rows=estimateRows();const subtotal=rows.reduce((a,r)=>a+r.amount,0);return subtotal*(1+(Number(project.reserve)||0)/100)}
function estimate(){let rows=estimateRows(),sum=rows.reduce((a,r)=>a+r.amount,0),reserve=sum*(Number(project.reserve)||0)/100;return `${heading('ШАГ 06 · БЮДЖЕТ','Смета ремонта',`Ориентировочная стоимость по городу ${safe(project.city)}. Резерв ${project.reserve}% учтён отдельно.`,`<div class="estimate-toolbar"><select class="select" id="city-select">${Object.keys(cities).map(c=>`<option ${project.city===c?'selected':''}>${c}</option>`).join('')}</select><select class="select" id="level-select">${['Эконом','Стандарт','Премиум'].map(l=>`<option ${project.workLevel===l?'selected':''}>${l}</option>`).join('')}</select><button class="button" data-action="export-csv">⇩ Excel / CSV</button><button class="button primary" data-action="print">PDF / Печать</button></div>`)}<div class="estimate-summary"><div class="card estimate-total"><label>МАТЕРИАЛЫ И ТОВАРЫ</label><strong>${money(rows.filter(r=>r.section.includes('Мебель')||r.section.includes('Освещение')||r.section==='Плитка'||r.section==='Отделка').reduce((a,r)=>a+r.amount,0))}</strong></div><div class="card estimate-total"><label>РАБОТЫ</label><strong>${money(rows.filter(r=>!r.section.includes('Мебель')&&!r.section.includes('Освещение')&&r.section!=='Плитка'&&r.section!=='Отделка').reduce((a,r)=>a+r.amount,0))}</strong></div><div class="card estimate-total"><label>РЕЗЕРВ ${project.reserve}%</label><strong>${money(reserve)}</strong></div><div class="card estimate-total" style="background:#eef3ec"><label>ИТОГО ОЦЕНКА</label><strong>${money(sum+reserve)}</strong></div></div><section class="card" style="overflow:hidden"><div style="padding:14px 16px;display:flex;justify-content:space-between;align-items:center"><div><b style="font:700 13px Manrope">Детализация по проекту</b><div style="font-size:9px;color:#969d93;margin-top:4px">Источник и дата указаны для каждой группы стоимости</div></div><button class="button small" data-action="add-estimate-row">＋ Своя позиция</button></div><div class="estimate-table-wrap"><table class="estimate-table"><thead><tr><th>РАЗДЕЛ</th><th>НАИМЕНОВАНИЕ</th><th>КОЛ-ВО</th><th>ЦЕНА / ЕД.</th><th>ИТОГО</th><th>ИСТОЧНИК</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="section-badge">${safe(r.section)}</span></td><td>${safe(r.name)}</td><td><input type="number" min="0" step=".1" value="${r.qty}" data-est-qty="${r.id}"></td><td><input type="number" min="0" step="10" value="${Math.round(r.amount/((r.qty||1)*(r.factor||1)))}" data-est-price="${r.id}"></td><td><b>${money(r.amount)}</b></td><td style="color:#858e82;font-size:9px">${safe(r.source)} · ${r.source.includes('Каталог')?'демо':'01.11.2026'}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="4">Резерв и непредвиденные расходы · ${project.reserve}%</td><td colspan="2">${money(reserve)}</td></tr><tr><td colspan="4">ИТОГО ПО ПРОЕКТУ</td><td colspan="2">${money(sum+reserve)}</td></tr></tfoot></table></div><div class="add-line"><label class="field-label" style="margin:0 0 6px">Резерв непредвиденных расходов</label><input id="reserve" class="input" style="width:120px" type="number" min="0" max="50" value="${project.reserve}"> <span style="font-size:9px;color:#9a9f96">% от стоимости работ и материалов</span></div></section><div class="estimate-bottom"><section class="card note-card"><h3>Точность оценки</h3><p>Работы: ориентировочный диапазон ±15%. Цены материалов и товаров демонстрационные, не подтверждены магазином. Проверьте стоимость, наличие и доставку до покупки. Смета не является офертой.</p></section><section class="card note-card"><h3>Городские расценки</h3><p>Коэффициент региона для ${safe(project.city)}: ${cities[project.city]||1}×. Уровень работ: ${safe(project.workLevel)}. Справочник в этом прототипе — демонстрационный и требует замены на проверенную базу расценок.</p></section></div>`}
