function addRoom(){const n=project.rooms.length+1, colors=['#eee8df','#e4ece6','#e6ecee','#f0ebdf'];project.rooms.push({id:'r'+Date.now(),name:`Комната ${n}`,type:'Комната',area:12,widthM:4,depthM:3,ceilingM:2.7,floor:project.floor,x:85+(n%3)*22,y:85+(n%2)*16,w:210,h:150,color:colors[n%colors.length]});save();render();toast('Комната добавлена')}
function editRoomModal(id){const r=project.rooms.find(x=>x.id===id);if(!r)return;showModal("Параметры помещения","Площадь, периметр и объём рассчитываются по введённой геометрии.",`<label class="field-label">Название</label><input class="input" name="name" value="${safe(r.name)}" required><label class="field-label">Назначение</label><select class="select" name="type">${["Гостиная","Спальня","Кухня","Ванная","Санузел","Прихожая","Кабинет","Детская","Балкон","Другое"].map(v=>`<option ${r.type===v?'selected':''}>${v}</option>`).join('')}</select><div class="modal-grid"><div><label class="field-label">Длина, м</label><input class="input" name="width" type="number" min="0.5" step="0.01" value="${r.widthM}" required></div><div><label class="field-label">Ширина, м</label><input class="input" name="depth" type="number" min="0.5" step="0.01" value="${r.depthM}" required></div><div><label class="field-label">Потолок, м</label><input class="input" name="ceiling" type="number" min="1.5" step="0.01" value="${r.ceilingM||2.7}" required></div></div>`,f=>{r.name=f.get('name');r.type=f.get('type');r.widthM=Number(f.get('width'));r.depthM=Number(f.get('depth'));r.ceilingM=Number(f.get('ceiling'));r.area=roomMetrics(r).area;r.w=roomW(r);r.h=roomH(r);save();render()})}
function addOpeningModal(){showModal("Добавить проём","Укажите тип, помещение и сторону стены.",`<label class="field-label">Тип</label><select class="select" name="kind"><option value="door">Дверь</option><option value="window">Окно</option><option value="arch">Арка</option><option value="balcony">Балконный блок</option></select><label class="field-label">Помещение</label><select class="select" name="room">${project.rooms.map(r=>`<option value="${r.id}">${safe(r.name)}</option>`).join('')}</select><div class="modal-grid"><div><label class="field-label">Ширина, мм</label><input class="input" name="width" type="number" value="900" min="300"></div><div><label class="field-label">Высота, мм</label><input class="input" name="height" type="number" value="2100" min="300"></div></div><label class="field-label">Стена</label><select class="select" name="side"><option value="top">Верхняя</option><option value="right">Правая</option><option value="bottom">Нижняя</option><option value="left">Левая</option></select>`,f=>{const r=project.rooms.find(x=>x.id===f.get('room')),side=f.get('side');let x=r.x+r.w/2,y=r.y+r.h/2;if(side==='top')y=r.y+5;else if(side==='bottom')y=r.y+r.h-5;else if(side==='left')x=r.x+5;else x=r.x+r.w-5;project.openings.push({id:'o'+Date.now(),room:r.id,kind:f.get('kind'),width:Number(f.get('width')),height:Number(f.get('height')),x,y});save();render()})}
function exportPlanSvg(){const svg=document.querySelector('#floor-svg');if(!svg)return;const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='plan-domproekt.svg';a.click();URL.revokeObjectURL(a.href);toast('План выгружен в SVG')}
function exportPlanPng(){const svg=document.querySelector('#floor-svg');if(!svg)return;const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'})),img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=1480;c.height=1000;c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='plan-domproekt.png';a.click();URL.revokeObjectURL(a.href);URL.revokeObjectURL(url);toast('План выгружен в PNG')})};img.onerror=()=>{URL.revokeObjectURL(url);toast('Не удалось подготовить PNG')};img.src=url}
function exportPlanDxf(){const lines=[];const add=(x1,y1,x2,y2)=>lines.push(`0\nLINE\n8\nWALLS\n10\n${Math.round(x1*20)}\n20\n${Math.round((500-y1)*20)}\n30\n0\n11\n${Math.round(x2*20)}\n21\n${Math.round((500-y2)*20)}\n31\n0\n`);for(const w of project.walls.filter(x=>(x.floor||1)===project.floor))add(w.x1,w.y1,w.x2,w.y2);for(const r of project.rooms.filter(x=>(x.floor||1)===project.floor)){const x=r.x,y=r.y,w=roomW(r),h=roomH(r);add(x,y,x+w,y);add(x+w,y,x+w,y+h);add(x+w,y+h,x,y+h);add(x,y+h,x,y)}const body='0\nSECTION\n2\nENTITIES\n'+lines.join('')+'0\nENDSEC\n0\nEOF\n',a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type:'application/dxf'}));a.download='plan-domproekt.dxf';a.click();URL.revokeObjectURL(a.href);toast('План экспортирован в DXF')}
async function importPlanDxf(file){try{const text=await file.text(),pairs=text.replace(/\r/g,'').split('\n');let entities=false,kind='',item={},segments=[];for(let i=0;i<pairs.length-1;i+=2){const code=pairs[i].trim(),val=pairs[i+1].trim();if(code==='2'&&val==='ENTITIES'){entities=true;continue}if(code==='0'&&val==='ENDSEC'){entities=false}if(!entities)continue;if(code==='0'){if(kind==='LINE'&&['x1','y1','x2','y2'].every(k=>Number.isFinite(item[k])))segments.push(item);kind=val;item={}}else if(kind==='LINE'&&['10','20','11','21'].includes(code)){item[({'10':'x1','20':'y1','11':'x2','21':'y2'})[code]]=Number(val)}}if(kind==='LINE'&&['x1','y1','x2','y2'].every(k=>Number.isFinite(item[k])))segments.push(item);if(!segments.length)throw new Error('В файле не найдены прямые линии DXF');const xs=segments.flatMap(x=>[x.x1,x.x2]),ys=segments.flatMap(x=>[x.y1,x.y2]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),scale=Math.min(680/Math.max(1,maxX-minX),440/Math.max(1,maxY-minY));for(const w of segments)project.walls.push({id:'dxf'+Date.now()+Math.random().toString(16).slice(2),floor:project.floor,x1:30+(w.x1-minX)*scale,y1:30+(maxY-w.y1)*scale,x2:30+(w.x2-minX)*scale,y2:30+(maxY-w.y2)*scale,type:'partition',name:'Импортированная стена',thickness:100});save();render();toast(`Импортировано линий: ${segments.length}`)}catch(err){toast(err.message||'Не удалось импортировать DXF')}}
async function uploadReferences(files){const chosen=[...files].slice(0,Math.max(0,20-(project.referenceImages||[]).length));if(!chosen.length){toast('Лимит — 20 референсов');return}for(const file of chosen){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Допустимы JPG, PNG и WebP');continue}if(file.size>10*1024*1024){toast(`${file.name}: превышен лимит 10 МБ`);continue}try{const res=await fetch('/api/uploads',{method:'POST',headers:{'content-type':file.type},body:file});const data=await res.json();if(!res.ok)throw new Error(data.error||'Загрузка не удалась');project.referenceImages.push({id:data.id,url:data.url,name:file.name,mimeType:data.mimeType,size:data.size});save()}catch(err){toast(err.message||'Ошибка загрузки');break}}render()}
function addRouteModal(){const pts=project.points.filter(p=>(!p.floor||p.floor===project.floor));if(pts.length<2){toast('Добавьте минимум две инженерные точки на этаже');return}showModal('Добавить трассу','Трасса прокладывается ортогонально между точками. Длина рассчитана по схеме.',`<label class="field-label">Система</label><select class="select" name="kind"><option value="electric">Кабель</option><option value="water">Водоснабжение</option><option value="drain">Канализация</option><option value="heating">Отопление</option><option value="vent">Вентиляция</option></select><label class="field-label">От точки</label><select class="select" name="from">${pts.map(p=>`<option value="${p.id}">${safe(p.name)} · ${safe(project.rooms.find(r=>r.id===p.room)?.name||'')}</option>`).join('')}</select><label class="field-label">До точки</label><select class="select" name="to">${pts.map((p,i)=>`<option value="${p.id}" ${i===1?'selected':''}>${safe(p.name)} · ${safe(project.rooms.find(r=>r.id===p.room)?.name||'')}</option>`).join('')}</select>`,f=>{const a=pts.find(p=>p.id===f.get('from')),b=pts.find(p=>p.id===f.get('to'));if(!a||!b||a.id===b.id){toast('Выберите разные точки');return}project.routes.push({id:'rt'+Date.now(),name:({electric:'Кабельная линия',water:'Водопровод',drain:'Канализация',heating:'Отопление',vent:'Вентиляция'})[f.get('kind')],kind:f.get('kind'),floor:project.floor,from:a.id,to:b.id,x1:a.x,y1:a.y,x2:b.x,y2:b.y,length:(Math.abs(b.x-a.x)+Math.abs(b.y-a.y))/50});save();render()})}
function addThing(kind){const room=project.rooms[0];if(!room)return;const id=String(kind).startsWith('p')?'p'+Date.now():'f'+Date.now();if(kind==='room')return addRoom();if(['socket','water','light','switch','radiator','vent'].includes(kind)){project.points.push({id,room:room.id,kind,name:({socket:'Розетка',water:'Вода',light:'Светильник',switch:'Выключатель',radiator:'Радиатор',vent:'Вентиляция'})[kind],x:room.x+room.w*.5,y:room.y+room.h*.5});}else project.items.push({id,room:room.id,kind,name:({sofa:'Диван',table:'Стол',bed:'Кровать',plant:'Растение',chair:'Стул',cabinet:'Шкаф',desk:'Стол рабочий'})[kind]||'Предмет',x:room.x+roomW(room)*.5,y:room.y+roomH(room)*.5,floor:project.floor});save();render();toast('Элемент добавлен на план')}
function bindWallDraw(svg){svg.addEventListener('click',e=>{if(tool!=='wall')return;const b=svg.getBoundingClientRect(),pt={x:Math.round((e.clientX-b.left)*740/b.width),y:Math.round((e.clientY-b.top)*500/b.height)};if(!drawStart){drawStart=pt;toast('Начало стены выбрано. Щёлкните в точке окончания.');return}const a=drawStart;drawStart=null;const len=(Math.hypot(pt.x-a.x,pt.y-a.y)/50).toFixed(2);showModal('Параметры стены',`Длина по плану: ${len} м.`, `<label class="field-label">Тип стены</label><select class="select" name="type"><option value="partition">Перегородка</option><option value="bearing">Несущая</option><option value="wet">Мокрая зона</option></select><label class="field-label">Толщина, мм</label><input class="input" name="thickness" type="number" min="100" max="380" value="100">`,f=>{const type=f.get('type');project.walls.push({id:'w'+Date.now(),floor:project.floor,x1:a.x,y1:a.y,x2:pt.x,y2:pt.y,type,thickness:Math.max(100,Math.min(380,Number(f.get('thickness'))||100)),name:type==='bearing'?'Несущая стена':'Стена'});save();render()})});svg.addEventListener('dblclick',e=>{const w=e.target.closest('[data-wall]');if(!w)return;const wall=project.walls.find(x=>x.id===w.dataset.wall);if(!wall)return;if(wall.type==='bearing'&&!confirm('Стена помечена как несущая. Удалить эскизный элемент?'))return;project.walls=project.walls.filter(x=>x.id!==wall.id);save();render();toast('Стена удалена. При необходимости используйте отмену.')})}
function bindFloorDrag(){const svg=document.querySelector('#floor-svg');if(!svg)return;bindWallDraw(svg);svg.addEventListener('pointerdown',e=>{const g=e.target.closest('.drag-item');if(!g)return;e.preventDefault();const box=svg.getBoundingClientRect(),pt=new DOMPoint((e.clientX-box.left)*740/box.width,(e.clientY-box.top)*500/box.height);dragState={id:g.dataset.id,type:g.dataset.type,svg,box};g.setPointerCapture?.(e.pointerId);});svg.addEventListener('pointermove',e=>{if(!dragState||dragState.svg!==svg)return;const x=(e.clientX-dragState.box.left)*740/dragState.box.width,y=(e.clientY-dragState.box.top)*500/dragState.box.height,arr=dragState.type==='point'?project.points:project.items,obj=arr.find(i=>i.id===dragState.id);if(obj){obj.x=Math.max(25,Math.min(715,x));obj.y=Math.max(25,Math.min(475,y));const el=svg.querySelector(`[data-id="${dragState.id}"]`);el?.setAttribute('transform',`translate(${obj.x} ${obj.y})`);}});svg.addEventListener('pointerup',()=>{if(dragState?.svg===svg){dragState=null;save()}});}
async function generateDesign(){const promptInput=document.querySelector('#prompt'),budgetInput=document.querySelector('#budget');if(promptInput)project.prompt=promptInput.value;if(budgetInput)project.budget=Number(budgetInput.value)||0;project.referenceConsent=!!document.querySelector('#reference-consent')?.checked;if((project.referenceImages||[]).length&&!project.referenceConsent){toast('Подтвердите передачу референсов выбранному ИИ или удалите фотографии');return}const provider=document.querySelector('#provider')?.value||'local';project.provider=provider;if(provider==='local'){const products=project.products.filter(p=>p.tags.some(t=>`${project.style} ${project.prompt}`.toLowerCase().includes(t.toLowerCase()))).slice(0,5);const picked=(products.length?products:project.products.slice(0,4)).map(p=>p.id);project.designs=[{id:'d'+Date.now(),provider:'демо',name:`${project.style} · спокойный дом`,description:`Подборка для вашей планировки в стиле «${project.style}». Учтён запрос: ${project.prompt||'гармоничный и удобный интерьер'}. ${picked.length?`Подобрано ${picked.length} позиций из каталога проекта.`:'В каталоге не нашлось подходящих позиций.'}`,productIds:picked},{id:'d'+(Date.now()+1),provider:'демо',name:`${project.style} · тёплый вариант`,description:'Альтернативная палитра и сочетания материалов на основе товаров, которые уже есть в каталоге.',productIds:project.products.slice(1,5).map(p=>p.id)}];project.selectedDesignId=null;save();render();toast('Готово: созданы два демо-варианта');return;}
  const btn=document.querySelector('[data-action="generate"]');if(btn){btn.disabled=true;btn.classList.add('loading');btn.textContent='Собираем варианты…'}try{const res=await fetch(`/api/design/${provider}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({prompt:project.prompt,style:project.style,city:project.city,rooms:project.rooms.filter(r=>!(project.preferences.designRooms||[]).length||project.preferences.designRooms.includes(r.id)).map(r=>({name:r.name,area:roomMetrics(r).area,perimeter:roomMetrics(r).perimeter,ceiling:r.ceilingM})),catalog:project.products.filter(p=>p.dimensions),references:(project.referenceImages||[]).map(r=>r.id),preferences:project.preferences})});const d=await res.json();if(!res.ok)throw new Error(d.error||'Не удалось обратиться к модели');project.designs=d.variants.map(v=>({id:v.id,provider:v.provider||provider,name:v.name,description:v.description,productIds:v.catalogIds}));project.selectedDesignId=null;save();render();toast('Варианты получены от '+(provider==='gemini'?'Gemini':'OpenAI'));}catch(e){if(btn){btn.disabled=false;btn.classList.remove('loading');btn.textContent='✳ Создать варианты'}toast(e.message)}}
function showModal(title,desc,fields,submit){const box=document.createElement('div');box.className='modal-backdrop';box.innerHTML=`<form class="modal"><h2>${title}</h2><p>${desc}</p>${fields}<div class="modal-actions"><button type="button" class="button" data-cancel>Отмена</button><button class="button primary">Сохранить</button></div></form>`;document.body.append(box);box.addEventListener('click',e=>{if(e.target===box||e.target.closest('[data-cancel]'))box.remove()});box.querySelector('form').addEventListener('submit',e=>{e.preventDefault();submit(new FormData(e.target));box.remove()});}
function addProductModal(){showModal('Добавить товар в каталог','Позиции сохраняются под уникальным ID. Укажите фактические данные и ссылку на карточку магазина.',`<label class="field-label">Название</label><input class="input" name="name" required><label class="field-label">Категория</label><select class="select" name="category"><option>Мебель</option><option>Сантехника</option><option>Плитка</option><option>Отделка</option><option>Освещение</option><option>Декор</option></select><label class="field-label">Цена, ₽</label><input class="input" name="price" type="number" min="0" required><label class="field-label">Размеры</label><input class="input" name="dimensions" required placeholder="Ш × Г × В мм"><label class="field-label">Ссылка магазина</label><input class="input" name="url" type="url" required placeholder="https://..."><label class="field-label">Теги через запятую</label><input class="input" name="tags" placeholder="скандинавский, дерево">`,async f=>{const url=f.get('url');try{const resp=await fetch('/api/catalog/check-url',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url})});if(!resp.ok)throw new Error('Проверьте ссылку товара');}catch(e){if(e.message!=='Failed to fetch'){toast(e.message);return;}}project.products.unshift({id:'user-'+Date.now(),name:f.get('name'),brand:'Добавлено пользователем',category:f.get('category'),price:Number(f.get('price')),dimensions:f.get('dimensions'),tags:String(f.get('tags')).split(',').map(s=>s.trim().toLowerCase()).filter(Boolean),emoji:'▦',store:new URL(url).hostname,url,updated:new Date().toLocaleDateString('ru-RU')});save();render();toast('Товар добавлен в каталог')})}
function splitRow(line,delimiter){const out=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&quoted){value+='"';i++;continue}if(c==='"'){quoted=!quoted;continue}if(c===delimiter&&!quoted){out.push(value.trim());value='';continue}value+=c}out.push(value.trim());return out}
function canonicalCategory(value){const s=String(value||'').toLowerCase();if(/плит|керамогранит/.test(s))return 'Плитка';if(/мебел|стол|диван|кроват|стул/.test(s))return 'Мебель';if(/сантех|ванн|смесител|раковин/.test(s))return 'Сантехника';if(/свет|люстр|ламп|освещ/.test(s))return 'Освещение';if(/обо|краск|ламинат|покрыт|отдел/.test(s))return 'Отделка';return value||'Стройматериалы'}
function parseYml(text){const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw new Error('Не удалось разобрать XML/YML-фид');const cats=new Map([...xml.querySelectorAll('categories category')].map(c=>[c.getAttribute('id'),c.textContent.trim()]));return [...xml.querySelectorAll('offer')].map(o=>{const get=n=>o.getElementsByTagName(n)[0]?.textContent?.trim()||'';const params=[...o.getElementsByTagName('param')].map(p=>`${p.getAttribute('name')||''}: ${p.textContent.trim()}`);const dims=params.filter(p=>/габарит|размер|ширин|высот|длин|dimension|width|height/i.test(p)).join('; ');const category=cats.get(get('categoryId'))||get('category');return {id:o.getAttribute('id')||get('vendorCode'),name:get('name')||get('model'),brand:get('vendor'),category,price:get('price'),url:get('url'),dimensions:dims||[o.getAttribute('width'),o.getAttribute('depth'),o.getAttribute('height')].filter(Boolean).join(' × '),tags:[category,get('vendor'),get('name'),...params].filter(Boolean).slice(0,12),image:get('picture'),store:''}}).filter(p=>p.name&&p.url&&Number(String(p.price).replace(',','.'))>0)}
function parseCsv(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(s=>s.trim());if(lines.length<2)return [];const delim=[';','\t',','].sort((a,b)=>lines[0].split(b).length-lines[0].split(a).length)[0];const headers=splitRow(lines[0],delim).map(s=>s.toLowerCase());const find=(row,keys)=>{const i=headers.findIndex(h=>keys.some(k=>h===k||h.includes(k)));return i<0?'':row[i]||''};return lines.slice(1).map(line=>{const r=splitRow(line,delim);const category=find(r,['category','категория','раздел']);return {id:find(r,['sku','артикул','offer_id','id']),name:find(r,['название','наименование','title','name']),brand:find(r,['бренд','производитель','vendor','brand']),category,price:find(r,['цена','price']),url:find(r,['ссылка','url','link']),dimensions:find(r,['габариты','размеры','dimensions','size']),tags:find(r,['теги','tags']).split(/[,|]/).map(s=>s.trim()),store:find(r,['магазин','поставщик','store'])}}).filter(p=>p.name&&p.url&&Number(String(p.price).replace(/\s/g,'').replace(',','.'))>0)}
function parseImportedProducts(text,file){const ext=file.name.split('.').pop().toLowerCase();if(ext==='json'){const data=JSON.parse(text);const rows=Array.isArray(data)?data:data.products||data.items||data.offers||[];return rows.map(p=>({id:p.id||p.sku||p.offerId,name:p.name||p.title,brand:p.brand||p.vendor,category:p.category,price:p.price,url:p.url||p.link,dimensions:p.dimensions||p.size,tags:p.tags||[],image:p.image||p.picture,store:p.store||p.vendor})).filter(p=>p.name&&p.url&&Number(p.price)>0)}if(['xml','yml','yaml'].includes(ext))return parseYml(text);return parseCsv(text)}
async function importCatalogFile(file){try{if(file.size>50*1024*1024)throw new Error('Файл больше лимита 50 МБ');const raw=parseImportedProducts(await file.text(),file);if(!raw.length)throw new Error('В файле не найдено товарных строк с названием, ценой и ссылкой');const existing=new Map(project.products.map((p,i)=>[p.url,i]));let added=0,updated=0,skipped=0;const today=new Date().toLocaleDateString('ru-RU');for(const row of raw){let link;try{link=new URL(row.url)}catch{skipped++;continue}if(!['https:','http:'].includes(link.protocol)){skipped++;continue}const price=Number(String(row.price).replace(/\s/g,'').replace(',','.'));if(!row.name||!(price>0)){skipped++;continue}const sku=String(row.id||row.url).replace(/[^\p{L}\p{N}-]/gu,'').slice(0,60);const product={id:`feed-${sku||Date.now()}-${Math.abs([...String(row.url)].reduce((a,c)=>((a<<5)-a+c.charCodeAt(0))|0,0))}`,name:String(row.name).slice(0,180),brand:String(row.brand||file.name).slice(0,100),category:canonicalCategory(row.category),price,dimensions:String(row.dimensions||'').slice(0,180),tags:(Array.isArray(row.tags)?row.tags:String(row.tags||'').split(/[,;|]/)).map(x=>String(x).trim().toLowerCase()).filter(Boolean).slice(0,30),emoji:'▦',store:String(row.store||file.name.replace(/\.[^.]+$/,'')).slice(0,80),url:link.href,updated:today,image:row.image||''};const idx=existing.get(product.url);if(idx!==undefined){project.products[idx]=product;updated++}else{existing.set(product.url,project.products.length);project.products.unshift(product);added++}}project.catalogImports??=[];project.catalogImports.push({file:file.name,added,updated,skipped,date:today});save();render();toast(`Каталог обновлён: +${added}, обновлено ${updated}, пропущено ${skipped}`)}catch(err){toast(err.message||'Не удалось импортировать фид')}}
function exportShoppingCsv(){const chosen=project.designs.find(d=>d.id===project.selectedDesignId),ids=[...new Set([...(chosen?.productIds||[]),...(project.manualShopping||[])])].filter(id=>!(project.shoppingExclusions||[]).includes(id)),items=ids.map(id=>project.products.find(p=>p.id===id)).filter(Boolean),rows=[['Магазин','Категория','Наименование','Размеры','Количество','Цена за шт.','Сумма','Ссылка','Обновлено'],...items.map(p=>{const q=Math.max(1,Number(project.shoppingQuantities?.[p.id])||1);return [p.store,p.category,p.name,p.dimensions,q,p.price,p.price*q,p.url,p.updated]})],csv=rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(';')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='spisok-pokupok-domproekt.csv';a.click();URL.revokeObjectURL(a.href);toast('Список покупок выгружен')}
function exportCsv(){const rows=estimateRows(),reserve=Number(project.reserve)||0;const text=[['Раздел','Наименование','Количество','Сумма, ₽','Источник'],...rows.map(r=>[r.section,r.name,r.qty,Math.round(r.amount),r.source]),['Резерв',`${reserve}%`,1,Math.round(rows.reduce((a,r)=>a+r.amount,0)*reserve/100),'Ручная настройка'],['ИТОГО','',1,Math.round(estimateTotal()),'Оценка']].map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));a.download='smeta-domproekt.csv';a.click();URL.revokeObjectURL(a.href);toast('Смета выгружена в CSV для Excel')}
document.body.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');if(nav)return go(nav.dataset.page);const chosenDesign=e.target.closest('[data-select-design]');if(chosenDesign){project.selectedDesignId=chosenDesign.dataset.selectDesign;save();render();return}const addShopping=e.target.closest('[data-add-shopping]');if(addShopping){project.manualShopping??=[];if(!project.manualShopping.includes(addShopping.dataset.addShopping))project.manualShopping.push(addShopping.dataset.addShopping);save();render();toast('Товар добавлен в список покупок');return}const goBtn=e.target.closest('[data-go]');if(goBtn)return go(goBtn.dataset.go);const styleBtn=e.target.closest('[data-style]');if(styleBtn){project.style=styleBtn.dataset.style;save();render();return}const toolBtn=e.target.closest('[data-tool]');if(toolBtn){tool=toolBtn.dataset.tool;drawStart=null;return render()}const add=e.target.closest('[data-add]');if(add)return addThing(add.dataset.add);const edit=e.target.closest('[data-edit-room]');if(edit)return editRoomModal(edit.dataset.editRoom);const rem=e.target.closest('[data-remove-room]');if(rem){project.rooms=project.rooms.filter(r=>r.id!==rem.dataset.removeRoom);save();render();return}const delPurchase=e.target.closest('[data-remove-purchase]');if(delPurchase){project.shoppingExclusions??=[];project.shoppingExclusions.push(delPurchase.dataset.removePurchase);save();render();return}const rr=e.target.closest('[data-remove-reference]');if(rr){project.referenceImages=project.referenceImages.filter(x=>x.id!==rr.dataset.removeReference);save();render();return}const rp=e.target.closest('[data-remove-point]');if(rp){project.points=project.points.filter(p=>p.id!==rp.dataset.removePoint);save();render();return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='overview'){page='overview';return render()}if(action==='resume'){resumeJourney();return}if(action==='complete-step'){completeCurrentStep();return}if(action==='skip-engineering'){skipEngineering();return}if(action==='previous-step'){const idx=journeySteps.findIndex(x=>x.id===page);go(idx<=0?'overview':journeySteps[idx-1].id);return}
 if(action==='add-room')return addRoom();if(action==='undo')return restoreHistory(undoStack,redoStack);if(action==='redo')return restoreHistory(redoStack,undoStack);if(action==='add-opening')return addOpeningModal();if(action==='add-route')return addRouteModal();if(action==='export-plan-svg')return exportPlanSvg();if(action==='add-references'){document.querySelector('#reference-files')?.click();return}if(action==='export-plan-dxf')return exportPlanDxf();if(action==='import-plan-dxf'){document.querySelector('#plan-file')?.click();return}if(action==='export-plan-png')return exportPlanPng();if(action==='add-point')return showModal('Добавить инженерную точку','Выберите систему и помещение.',`<label class="field-label">Тип точки</label><select class="select" name="kind"><option value="socket">Розетка</option><option value="switch">Выключатель</option><option value="light">Светильник</option><option value="water">Точка воды</option><option value="radiator">Радиатор</option><option value="vent">Вентиляция</option></select><label class="field-label">Помещение</label><select class="select" name="room">${project.rooms.map(r=>`<option value="${r.id}">${safe(r.name)}</option>`).join('')}</select>`,f=>{const k=f.get('kind'),r=project.rooms.find(x=>x.id===f.get('room'));project.points.push({id:'p'+Date.now(),room:r.id,kind:k,name:({socket:'Розетка',switch:'Выключатель',light:'Светильник',water:'Точка воды',radiator:'Радиатор',vent:'Вентиляция'})[k],x:r.x+roomW(r)/2,y:r.y+roomH(r)/2,height:k==="socket"?300:k==="switch"?900:2400,floor:project.floor,powerW:0});save();render()});if(action==='import-feed'){document.querySelector('#feed-file')?.click();return}if(action==='add-product')return addProductModal();if(action==='generate')return generateDesign();if(action==='toggle-furniture'){project.layers.furniture=!project.layers.furniture;save();return render()}if(action==='toggle-engine-layer'){project.layers.electricity=!project.layers.electricity;save();return render()}if(action==='toggle-water'){project.layers.water=!project.layers.water;save();return render()}if(action==='toggle-heating'){project.layers.heating=!project.layers.heating;save();return render()}if(action==='toggle-vent'){project.layers.ventilation=!project.layers.ventilation;save();return render()}if(action==='zoom-in'||action==='zoom-out'){toast('Масштаб схемы можно менять прокруткой в следующей версии');return}if(action==='print'){window.print();return}if(action==='export-csv')return exportCsv();if(action==='export-shopping')return exportShoppingCsv();if(action==='add-estimate-row')return showModal('Своя строка сметы','Добавьте расход с количеством и ценой.',`<label class="field-label">Раздел</label><select class="select" name="section"><option>Дополнительные работы</option><option>Материалы</option><option>Доставка</option><option>Другое</option></select><label class="field-label">Название</label><input class="input" name="name" required><label class="field-label">Количество</label><input class="input" name="qty" type="number" min="0" step=".1" value="1"><label class="field-label">Цена за единицу, ₽</label><input class="input" name="price" type="number" min="0" required>`,f=>{project.addedLines.push({section:f.get('section'),name:f.get('name'),qty:Number(f.get('qty'))||1,price:Number(f.get('price'))||0});save();render()});if(action==='rename')return showModal('Параметры проекта','Название и город расчёта.',`<label class="field-label">Название проекта</label><input class="input" name="name" value="${safe(project.name)}" required><label class="field-label">Город</label><select class="select" name="city">${Object.keys(cities).map(c=>`<option ${project.city===c?'selected':''}>${c}</option>`).join('')}</select>`,f=>{project.name=f.get('name');project.city=f.get('city');save();render()});if(action==='remove-design'){project.designs=project.designs.filter(d=>d.id!==e.target.closest('[data-id]')?.dataset.id);save();render()}
});
document.body.addEventListener('change',e=>{if(e.target.matches('[data-design-room]')){project.preferences.designRooms??=[];project.preferences.designRooms=e.target.checked?[...new Set([...project.preferences.designRooms,e.target.dataset.designRoom])]:project.preferences.designRooms.filter(id=>id!==e.target.dataset.designRoom);save()}if(e.target.dataset.shoppingQty){project.shoppingQuantities??={};project.shoppingQuantities[e.target.dataset.shoppingQty]=Math.max(1,Number(e.target.value)||1);save();render()}if(e.target.id==='city-select'){project.city=e.target.value;save();render()}if(e.target.id==='level-select'){project.workLevel=e.target.value;save();render()}if(e.target.id==='floor-select'){if(e.target.value==='add'){project.floor=Math.max(...(project.floors||[1]))+1;project.floors.push(project.floor);toast('Добавлен этаж '+project.floor)}else project.floor=Number(e.target.value)||1;save();render()}if(e.target.id==='reserve'){project.reserve=Math.max(0,Math.min(50,Number(e.target.value)||0));save();render()}if(e.target.classList.contains('tile-input')){project.tile[e.target.dataset.key]=Math.max(.05,Number(e.target.value)||.05);save();render()}if(e.target.id==='tile-pattern'){project.tile.pattern=e.target.value;save();render()}if(e.target.id==='tile-joint'){project.tile.joint=Number(e.target.value);save();render()}if(e.target.id==='tile-waste'){project.tile.waste=Number(e.target.value);save();render()}if(e.target.id==='catalog-category'){catalogCategory=e.target.value;render()}if(e.target.id==='provider'){project.provider=e.target.value;save()}if(e.target.id==='reference-files'){const files=e.target.files;if(files?.length)uploadReferences(files);e.target.value=''}if(e.target.id==='plan-file'){ const file=e.target.files?.[0];if(file)importPlanDxf(file);e.target.value=''}if(e.target.id==='feed-file'){const file=e.target.files?.[0];if(file)importCatalogFile(file);e.target.value=''}if(e.target.dataset.estQty||e.target.dataset.estPrice){const id=e.target.dataset.estQty||e.target.dataset.estPrice;project.estimateEdits??={};project.estimateEdits[id]??={};if(e.target.dataset.estQty)project.estimateEdits[id].qty=Number(e.target.value)||0;if(e.target.dataset.estPrice)project.estimateEdits[id].price=Number(e.target.value)||0;save();render()} });
document.body.addEventListener('input',e=>{if(e.target.id==='catalog-search'){catalogQuery=e.target.value;const pos=e.target.selectionStart;render();const inp=document.querySelector('#catalog-search');inp?.focus();inp?.setSelectionRange(pos,pos)}if(e.target.id==='prompt'){project.prompt=e.target.value;save()}if(e.target.dataset.pref){project.preferences??={};project.preferences[e.target.dataset.pref]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(e.target.value):e.target.value;save()}if(e.target.id==='reference-consent'){project.referenceConsent=e.target.checked;save()}if(e.target.id==='budget'){project.budget=Math.max(0,Number(e.target.value)||0);save()}if(e.target.dataset.estQty||e.target.dataset.estPrice){const all=estimateRows(),id=e.target.dataset.estQty||e.target.dataset.estPrice;const row=all.find(r=>r.id===id);if(!row)return;project.estimateEdits??={};project.estimateEdits[id]??={};if(e.target.dataset.estQty)project.estimateEdits[id].qty=Number(e.target.value);if(e.target.dataset.estPrice)project.estimateEdits[id].price=Number(e.target.value);save();}});
app.addEventListener('toggle',e=>{if(e.target.matches?.('.shopping-details'))shoppingPanel=e.target.open?e.target.dataset.panel:''},true);
document.body.addEventListener('click',e=>{const v=e.target.closest('[data-variant]');if(v){const d=project.designs.find(x=>x.id===v.dataset.variant);toast(d?`Вариант включает ${d.productIds.length} каталожных позиций`:'Вариант не найден')}});
async function init(){try{const sourceResponse=await fetch('/retail-sources.json');if(sourceResponse.ok)retailSources=await sourceResponse.json()}catch{}try{const r=await fetch('/api/health');if(r.ok)providerStatus=(await r.json()).providers||{};}catch{}try{const r=await fetch('/api/project');if(r.ok){const remote=await r.json();if(remote?.rooms?.length&&!localStorage.getItem(STORE)){project={...project,...remote};localStorage.setItem(STORE,JSON.stringify(project))}}}catch{}render()}
init();
